package messages

import (
	"fmt"

	"github.com/libp2p/go-libp2p-core/peer"
	btss "gitlab.com/thorchain/tss/tss-lib-private.git/v3/tss"
)

// THORChainTSSMessageType  represent the message type used in THORChain TSS
type THORChainTSSMessageType uint8

const (
	// TSSKeyGenMsg is the message directly generated by tss-lib package
	TSSKeyGenMsg THORChainTSSMessageType = iota
	// TSSKeySignMsg is the message directly generated by tss lib for sign
	TSSKeySignMsg
	// TSSKeyGenVerMsg is the message we create on top to make sure everyone received the same message
	TSSKeyGenVerMsg
	// TSSKeySignVerMsg is the message we create to make sure every party receive the same broadcast message
	TSSKeySignVerMsg
	// TSSControlMsg is the message we create to exchange Tss share
	TSSControlMsg
	// TSSTaskDone is the message of Tss process notification
	TSSTaskDone
	// TSSFrostPreprocessMsg is round-1 preprocess exchange for FROST signing
	TSSFrostPreprocessMsg
	// TSSFrostShareMsg is round-2 signature share exchange for FROST signing
	TSSFrostShareMsg
	// TSSFrostVerifyMsg is per-round transcript hash verification for FROST messages
	TSSFrostVerifyMsg
	// TSSFrostResultMsg is final result propagation for non-active signers
	TSSFrostResultMsg
	// TSSFrostDKGRound1Msg is round-1 commitment exchange for FROST DKG
	TSSFrostDKGRound1Msg
	// TSSFrostDKGRound2Msg is round-2 encrypted share exchange for FROST DKG
	TSSFrostDKGRound2Msg
	// TSSFrostDKGRound3Msg is round-3 result exchange for FROST DKG
	TSSFrostDKGRound3Msg
	// TSSFrostDKGResultMsg is final DKG result propagation for non-active signers
	TSSFrostDKGResultMsg
	// Unknown is the message indicates the undefined message type
	Unknown
)

// String implement fmt.Stringer
func (msgType THORChainTSSMessageType) String() string {
	switch msgType {
	case TSSKeyGenMsg:
		return "TSSKeyGenMsg"
	case TSSKeySignMsg:
		return "TSSKeySignMsg"
	case TSSKeyGenVerMsg:
		return "TSSKeyGenVerMsg"
	case TSSKeySignVerMsg:
		return "TSSKeySignVerMsg"
	case TSSFrostPreprocessMsg:
		return "TSSFrostPreprocessMsg"
	case TSSFrostShareMsg:
		return "TSSFrostShareMsg"
	case TSSFrostVerifyMsg:
		return "TSSFrostVerifyMsg"
	case TSSFrostResultMsg:
		return "TSSFrostResultMsg"
	case TSSFrostDKGRound1Msg:
		return "TSSFrostDKGRound1Msg"
	case TSSFrostDKGRound2Msg:
		return "TSSFrostDKGRound2Msg"
	case TSSFrostDKGRound3Msg:
		return "TSSFrostDKGRound3Msg"
	case TSSFrostDKGResultMsg:
		return "TSSFrostDKGResultMsg"
	default:
		return "Unknown"
	}
}

// WrappedMessage is a message with type in it
type WrappedMessage struct {
	MessageType THORChainTSSMessageType `json:"message_type"`
	MsgID       string                  `json:"message_id"`
	Payload     []byte                  `json:"payload"`
}

// BroadcastMsgChan is the channel structure for keygen/keysign submit message to p2p network
type BroadcastMsgChan struct {
	WrappedMessage WrappedMessage
	PeersID        []peer.ID
}

// BroadcastConfirmMessage is used to broadcast to all parties what message they receive
type BroadcastConfirmMessage struct {
	P2PID string `json:"P2PID"`
	Key   string `json:"key"`
	Hash  string `json:"hash"`
}

// WireMessage the message that produced by tss-lib package
type WireMessage struct {
	Routing   *btss.MessageRouting `json:"routing"`
	RoundInfo string               `json:"round_info"`
	Message   []byte               `json:"message"`
	Sig       []byte               `json:"signature"`
}

// GetCacheKey return the key we used to cache it locally
func (m *WireMessage) GetCacheKey() string {
	return fmt.Sprintf("%s-%s", m.Routing.From.Id, m.RoundInfo)
}

type TssControl struct {
	ReqHash     string                  `json:"reqest_hash"`
	ReqKey      string                  `json:"request_key"`
	RequestType THORChainTSSMessageType `json:"request_type"`
	Msg         *WireMessage            `json:"message_body"`
}

type TssTaskNotifier struct {
	TaskDone bool `json:"task_done"`
}
